class SectionBoundary extends Component {
  constructor(props) { super(props); this.state = { failed: false }; }
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidUpdate(previous) { if (previous.section !== this.props.section && this.state.failed) this.setState({ failed: false }); }
  render() { return this.state.failed ? <EmptyState icon="warning" title="No se pudo abrir esta sección" description="Ocurrió un problema inesperado al mostrar el contenido." action={<button className="btn primary" onClick={() => this.setState({ failed: false })}>Reintentar</button>} /> : this.props.children; }
}

function Notice({ msg }) {
  return msg ? <div className={`feedback ${msg.kind}`} role={msg.kind === "error" ? "alert" : "status"}><Icon name={msg.kind === "error" ? "warning" : "check"} size={18} /><span>{msg.text}</span></div> : null;
}

function Load({ loading, error, retry, items, empty, children, emptyIcon = "document" }) {
  if (loading) return <SkeletonRows />;
  if (error) return <EmptyState icon="warning" title="No pudimos cargar la información" description={error} action={<button className="btn secondary" onClick={retry}>Volver a intentar</button>} />;
  return items?.length ? children : <EmptyState icon={emptyIcon} title={empty} description="Cuando haya información disponible, la vas a encontrar acá." />;
}

function PasswordField({ label, value, onChange, minLength, required, autoComplete, hint }) {
  const [show, setShow] = useState(false);
  const inputId = `password-${label.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-")}`;
  return <div className="field"><label htmlFor={inputId}>{label}</label><div className="password-input"><input id={inputId} type={show ? "text" : "password"} value={value} minLength={minLength} required={required} autoComplete={autoComplete} onChange={event => onChange(event.target.value)} /><button type="button" className="password-toggle" aria-label={show ? "Ocultar contraseña" : "Mostrar contraseña"} aria-pressed={show} onClick={() => setShow(value => !value)}>{show ? "Ocultar" : "Mostrar"}</button></div>{hint && <small className="field-hint">{hint}</small>}</div>;
}

function ConfirmModal({ item, onCancel, onConfirm }) {
  return <Modal open={Boolean(item)} title={item?.title || "Confirmar acción"} eyebrow="Confirmación" onClose={onCancel} busy={item?.busy} className="confirm-modal"><p>{item?.message}</p>{item?.context && <div className="modal-context"><Icon name="warning" size={18} /><span>{item.context}</span></div>}<div className="modal-actions"><button className="btn secondary" disabled={item?.busy} onClick={onCancel}>Cancelar</button><button className="btn danger" disabled={item?.busy} onClick={onConfirm}>{item?.busy ? "Procesando…" : item?.label || "Confirmar"}</button></div></Modal>;
}

function useApi(path) {
  const [state, setState] = useState({ loading: true, items: [], error: "" });
  const gate = useRef();
  if (!gate.current) gate.current = createRequestGate();
  const load = useCallback(async () => {
    const request = gate.current.start();
    setState({ loading: true, items: [], error: "" });
    try {
      const result = await api(path, { signal: request.signal });
      if (gate.current.isCurrent(request)) setState({ loading: false, items: Array.isArray(result?.items) ? result.items : [], error: "" });
    } catch (error) {
      if (gate.current.isCurrent(request)) setState({ loading: false, items: [], error: error.message });
    } finally { gate.current.release(request); }
  }, [path]);
  useEffect(() => { load(); return () => gate.current.cancel(); }, [load]);
  return { ...state, load };
}

const safe = value => String(value).replace(/[<>&]/g, "");
async function openPdf(id, action, onError) {
  const tab = window.open("", "_blank");
  if (tab) { tab.document.write("<!doctype html><title>Abriendo recibo…</title><style>body{display:grid;place-items:center;height:100vh;margin:0;font:16px system-ui;color:#15233f;background:#f3f5f8}main{padding:32px;border-radius:16px;background:white}</style><main><strong>Abriendo recibo…</strong><p>Preparando el acceso seguro al PDF.</p></main>"); tab.document.close(); }
  try { const { url } = await api(`/payslips/${id}/${action}`); tab ? tab.location.replace(url) : window.location.assign(url); return true; }
  catch (error) { if (tab) { tab.document.open(); tab.document.write(`<h1>No se pudo abrir el recibo</h1><p>${safe(error.message)}</p>`); tab.document.close(); } onError?.(error.message); return false; }
}

