  const open = async (item, action) => { if (await openPdf(item.id, action, onError)) { query.load(); onRead?.(); } };
  return <div className="employee-module"><PageHeader eyebrow="Documentación" title="Mis recibos" description="Consultá y descargá tus documentos salariales de forma segura." /><Load {...query} empty="Todavía no tenés recibos disponibles" emptyIcon="receipts"><div className="personal-receipts-grid">{query.items.map(item => <article className={`personal-receipt-card ${item.unread ? "unread" : ""}`} key={item.id}><div className="receipt-document-icon"><Icon name="receipts" size={23} /></div><div className="personal-receipt-main"><div className="receipt-title-line"><h2>{item.periodLabel}</h2>{item.unread && <StatusBadge tone="warning">Nuevo</StatusBadge>}</div><p>{TYPES[item.documentType]}</p></div><div className="personal-receipt-actions"><button className="btn secondary" onClick={() => open(item, "view")}><Icon name="eye" size={17} /> Ver</button><button className="btn primary" onClick={() => open(item, "download")}><Icon name="download" size={17} /> Descargar</button></div></article>)}</div></Load></div>;
