function EmployeeHome({ user, onUserChange }) {
  const [section, setSection] = useState(user.profileNeedsReview ? "profile" : "announcements"), [error, setError] = useState(""), [unread, setUnread] = useState(0);
  const loadUnread = () => api("/me/payslips/unread-count").then(result => setUnread(result.count)).catch(() => {}), refreshUser = () => api("/auth/me").then(result => onUserChange(result.user)), logout = () => { setAccessToken(null); api("/auth/logout", { method: "POST" }).finally(() => location.reload()); };
  useEffect(() => { if (can(user, "PAYSLIP_VIEW_OWN")) loadUnread(); }, []);
  const navigation = [["announcements", "Avisos", "announcements"], can(user, "PAYSLIP_VIEW_OWN") && ["receipts", "Mis recibos", "receipts"], ["profile", "Datos personales", "profile"]].filter(Boolean);
  return <div className="employee-shell"><header className="employee-header"><button className="employee-brand" onClick={() => setSection("announcements")}><img src={logo} alt="" /><span><strong>Instituto Urquiza</strong><small>Portal del personal</small></span></button><div className="employee-header-actions"><span className="employee-greeting">Hola, {user.firstName || user.email}</span><button className="btn secondary small" onClick={logout}><Icon name="logout" size={17} /> Salir</button></div></header><nav className="employee-nav">{navigation.map(([id, label, icon]) => <button key={id} className={section === id ? "active" : ""} onClick={() => setSection(id)}><Icon name={icon} size={18} /><span>{label}</span>{id === "receipts" && unread > 0 && <span className="nav-count">{unread}</span>}{id === "profile" && user.profileNeedsReview && <span className="nav-count">!</span>}</button>)}</nav><main className="employee-content">{user.profileNeedsReview && section !== "profile" && <div className="profile-reminder"><span className="reminder-icon"><Icon name="clock" size={21} /></span><div><strong>Es momento de revisar tus datos personales</strong><span>Pasaron tres meses desde la última actualización.</span></div><button className="btn secondary small" onClick={() => setSection("profile")}>Revisar ahora</button></div>}<Notice msg={error ? feedback(error, "error") : null} />{section === "profile" ? <PersonalProfile reviewDue={user.profileNeedsReview} onSaved={refreshUser} /> : section === "receipts" ? <EmployeePayslips onError={setError} onRead={loadUnread} /> : <EmployeeAnnouncements onError={setError} />}</main></div>;
}

function ChangePassword({ onDone }) {
  const [currentPassword, setCurrentPassword] = useState(""), [newPassword, setNewPassword] = useState(""), [message, setMessage] = useState(null), [busy, setBusy] = useState(false);
  const submit = async event => { event.preventDefault(); setBusy(true); try { await api("/auth/change-password", { method: "POST", body: JSON.stringify({ currentPassword, newPassword }) }); onDone(); } catch (error) { setMessage(feedback(error.message, "error")); } finally { setBusy(false); } };
  return <main className="auth-page"><form className="auth-card change-password-card" onSubmit={submit}><img src={logo} alt="Instituto Urquiza" className="auth-logo" /><span className="auth-step"><Icon name="lock" size={18} /> Seguridad de la cuenta</span><h1>Creá una nueva contraseña</h1><p className="auth-description">Por seguridad, tenés que reemplazar la contraseña temporal antes de continuar.</p><PasswordField label="Contraseña actual" value={currentPassword} onChange={setCurrentPassword} autoComplete="current-password" required /><PasswordField label="Nueva contraseña" value={newPassword} onChange={setNewPassword} minLength="12" autoComplete="new-password" required hint="Usá al menos 12 caracteres." /><Notice msg={message} /><button className="btn primary full" disabled={busy}>{busy ? "Guardando…" : "Guardar y continuar"}</button></form></main>;
}

export default function App() {
  const [user, setUser] = useState();
  useEffect(() => { api("/auth/refresh", { method: "POST" }).then(result => { setAccessToken(result.accessToken); setUser(result.user); }).catch(() => setUser(null)); }, []);
  useEffect(() => user ? startPresenceHeartbeat() : undefined, [user?.id]);
  const refreshUser = () => api("/auth/me").then(result => setUser(result.user));
  if (user === undefined) return <main className="splash-screen"><img src={logo} alt="Instituto Urquiza" /><span className="spinner" /><p>Preparando tu espacio…</p></main>;
  if (!user) return <Login onLogin={setUser} />;
  if (user.mustChangePassword) return <ChangePassword onDone={refreshUser} />;
  if (user.employeeId && !user.profileComplete) return <PersonalProfile required onSaved={refreshUser} />;
  const logout = () => { setAccessToken(null); api("/auth/logout", { method: "POST" }).finally(() => location.reload()); };
  return ["PAYSLIP_MANAGE", "EMPLOYEE_MANAGE", "USER_MANAGE", "ANNOUNCEMENT_MANAGE"].some(permission => can(user, permission)) ? <Admin user={user} onLogout={logout} /> : <EmployeeHome user={user} onUserChange={setUser} />;
}
